"""Generate apps/web/src/styles/tokens.css from docs/architecture/design-tokens.json.

Usage (from repository root):
    python3 tools/design-tokens/build_css.py            # write the file
    python3 tools/design-tokens/build_css.py --check    # exit 1 if the file is out of date (CI)
"""
import json
import sys
from pathlib import Path

SOURCE = Path("docs/architecture/design-tokens.json")
TARGET = Path("apps/web/src/styles/tokens.css")


def var(name: str) -> str:
    return "--lz-" + name.replace(".", "-")


def render(tokens: dict) -> str:
    lines = [
        "/* GENERATED by tools/design-tokens/build_css.py from docs/architecture/design-tokens.json. Do not edit by hand. */",
        "",
        ":root {",
    ]
    for group, values in tokens["primitive"].items():
        for key, value in values.items():
            lines.append(f"  {var(group + '.' + key)}: {value};")
    lines.append("}")
    default_key = next(iter(tokens["themes"]))
    for key, theme in tokens["themes"].items():
        selector = f':root,\n[data-theme="{key}"]' if key == default_key else f'[data-theme="{key}"]'
        lines += ["", f"{selector} {{"]
        for name, value in theme["color"].items():
            lines.append(f"  {var('color.' + name)}: {value};")
        for name, primitive in theme["radius"].items():
            lines.append(f"  {var('radius.' + name)}: var({var('radius.' + primitive)});")
        for name, value in theme["shadow"].items():
            lines.append(f"  {var('shadow.' + name)}: {value};")
        lines.append(f"  --lz-font-ui: var(--lz-font-family-{slug(theme['font']['ui'])});")
        lines.append(f"  --lz-font-display: var(--lz-font-family-{slug(theme['font']['display'])});")
        lines.append("}")
    lines += [
        "",
        "@media (prefers-reduced-motion: reduce) {",
        "  :root {",
        *[f"    {var('duration.' + k)}: 0ms;" for k in tokens["primitive"]["duration"]],
        "  }",
        "}",
        "",
        '[data-decor="reduced"] .lz-decor {',
        "  display: none;",
        "}",
        "",
    ]
    return "\n".join(lines)


def slug(font: str) -> str:
    return font.lower().replace(" ", "-")


def main() -> int:
    css = render(json.loads(SOURCE.read_text(encoding="utf-8")))
    if "--check" in sys.argv:
        if not TARGET.exists() or TARGET.read_text(encoding="utf-8") != css:
            print(f"{TARGET} is out of date; run python3 tools/design-tokens/build_css.py")
            return 1
        print(f"{TARGET} is up to date")
        return 0
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_text(css, encoding="utf-8")
    print(f"wrote {TARGET}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
